// Static facility map. All walls/crates/doors are axis-aligned boxes that block
// movement and bullets. Coordinates: x = east, z = north.

const WALL_T = 0.4;
const WALL_H = 4;

function hSegments(x1, x2, z, gaps = []) {
  const spans = [];
  let cur = x1;
  const sorted = [...gaps].sort((a, b) => a[0] - b[0]);
  for (const [g0, g1] of sorted) {
    if (g0 > cur) spans.push([cur, g0, z]);
    cur = Math.max(cur, g1);
  }
  if (x2 > cur) spans.push([cur, x2, z]);
  return spans;
}

function vSegments(z1, z2, x, gaps = []) {
  const spans = [];
  let cur = z1;
  const sorted = [...gaps].sort((a, b) => a[0] - b[0]);
  for (const [g0, g1] of sorted) {
    if (g0 > cur) spans.push([x, cur, g0]);
    cur = Math.max(cur, g1);
  }
  if (z2 > cur) spans.push([x, cur, z2]);
  return spans;
}

let boxIdCounter = 0;
function wallBoxes(segments, orientation) {
  return segments.map(([a, b, c]) => {
    if (orientation === 'h') {
      return {
        id: `w${boxIdCounter++}`,
        kind: 'wall',
        minX: Math.min(a, b),
        maxX: Math.max(a, b),
        minZ: c - WALL_T / 2,
        maxZ: c + WALL_T / 2,
        minY: 0,
        maxY: WALL_H,
      };
    }
    return {
      id: `w${boxIdCounter++}`,
      kind: 'wall',
      minX: a - WALL_T / 2,
      maxX: a + WALL_T / 2,
      minZ: Math.min(b, c),
      maxZ: Math.max(b, c),
      minY: 0,
      maxY: WALL_H,
    };
  });
}

