#objectives, #weapon-panel, #inventory-panel {
  background: rgba(10,16,22,0.66); border: 1px solid rgba(130,170,210,0.2);
  border-radius: 6px; padding: 10px 12px; margin-bottom: 8px;
}
#objective-list { list-style: none; text-align: left; }
#objective-list li { padding: 3px 0; font-size: 14px; color: #cdd8e4; }
#objective-list li.done { color: #6fdd92; text-decoration: line-through; }
#objective-list li::before { content: "▢ "; }
#objective-list li.done::before { content: "✓ "; }
#extraction-status { margin-top: 6px; font-size: 13px; color: #8aa0b5; text-align: left; }
#extraction-status.open { color: #5dff96; }

#weapon-name { font-size: 17px; font-weight: bold; color: #dce6f0; }
#ammo-display { font-size: 30px; font-weight: bold; margin: 2px 0; }
#ammo-mag { color: #fff; }
#reload-hint { color: #ffd84d; font-size: 13px; }
#weapon-slots { display: flex; gap: 8px; justify-content: flex-end; margin-top: 4px; }
#weapon-slots span { font-size: 11px; padding: 2px 6px; border: 1px solid rgba(255,255,255,0.18); border-radius: 3px; color: #8aa0b5; }
#weapon-slots span.active { color: #fff; border-color: #6fa8d8; background: rgba(111,168,216,0.2); }

#inv-slots { display: flex; flex-direction: column; gap: 3px; }
.inv-slot { display: flex; justify-content: space-between; font-size: 12px; padding: 2px 6px; border-radius: 3px; background: rgba(255,255,255,0.05); }
.inv-slot .key { color: #6fa8d8; }
#inventory-panel { text-align: left; }

#interact-prompt {
  position: absolute; left: 50%; top: 62%; transform: translateX(-50%);
  background: rgba(10,16,22,0.82); border: 1px solid rgba(130,170,210,0.4);
  padding: 8px 18px; border-radius: 5px; font-size: 15px;
}
#objective-progress {
  position: absolute; left: 50%; top: 68%; transform: translateX(-50%);
  width: 220px; height: 8px; background: rgba(0,0,0,0.6); border-radius: 4px; overflow: hidden;
}
#objective-progress-bar { height: 100%; width: 0; background: linear-gradient(90deg, #4dd2ff, #a0f0ff); }

#notifications { position: absolute; left: 50%; top: 16%; transform: translateX(-50%); display: flex; flex-direction: column; gap: 6px; align-items: center; }
#notifications .note {
  background: rgba(10,16,22,0.82); border: 1px solid rgba(130,170,210,0.35);
  padding: 7px 16px; border-radius: 4px; font-size: 14px;
  animation: fadein 0.2s;
}
@keyframes fadein { from { opacity: 0; transform: translateY(-8px); } to { opacity: 1; } }

#damage-vignette {
  position: absolute; inset: 0; pointer-events: none; opacity: 0;
  background: radial-gradient(ellipse at center, transparent 45%, rgba(255,0,0,0.55) 100%);
}
#lowhp-vignette {
  position: absolute; inset: 0; pointer-events: none; opacity: 0;
  background: radial-gradient(ellipse at center, transparent 55%, rgba(180,0,0,0.7) 100%);
  animation: pulse 1.2s infinite;
}
@keyframes pulse { 0%, 100% { opacity: 0.25; } 50% { opacity: 0.65; } }

#controls-hint {
  position: absolute; bottom: 6px; left: 50%; transform: translateX(-50%);
  font-size: 11px; color: rgba(200,215,230,0.55);
}

.settings-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px 24px; margin: 10px 0 18px; }
.settings-grid label { display: flex; flex-direction: column; gap: 6px; font-size: 14px; color: #bccadc; }
input[type="range"], select {
  accent-color: #6fa8d8; background: #141c26; color: #e8ecf1;
  border: 1px solid rgba(130,170,210,0.3); border-radius: 4px; padding: 6px;
}
.error-text { color: #ff8a7a; font-size: 13px; min-height: 18px; }

.save-slot {
  display: flex; justify-content: space-between; align-items: center;
  background: rgba(255,255,255,0.05); border: 1px solid rgba(130,170,210,0.2);
  border-radius: 6px; padding: 12px 16px; margin-bottom: 10px;
}
.save-slot .info { text-align: left; }
.save-slot .corrupt { color: #ff8a7a; }
.save-slot .empty { color: #778899; }
.save-slot button { margin-left: 8px; padding: 7px 14px; font-size: 14px; }

#end-stats { margin: 16px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px 30px; font-size: 15px; }
#end-stats .k { color: #8aa0b5; }
#end-reason { color: #ffb199; font-size: 15px; margin-bottom: 8px; }
#end-screen .won h2 { color: #6fdd92; }
#end-screen .lost h2 { color: #ff6655; }
#save-quick-info { margin-top: 14px; font-size: 12px; color: #778899; text-align: center; }

#toast {
  position: fixed; bottom: 40px; left: 50%; transform: translateX(-50%);
  z-index: 80; background: rgba(20,28,38,0.95); border: 1px solid rgba(130,170,210,0.4);
  padding: 10px 22px; border-radius: 6px; font-size: 14px;
}

